#!/usr/bin/perl
# Batch differential probe: each line of the input file is a whitespace-separated
# argv (already spelled), fed to both binaries; reports byte diffs.
use strict; use warnings;
my $CPP="/workspace/dataset/test20_executable";
my $RUST="/output/test20";
my $file=shift or die "usage: probe.pl file\n";
open(my $fh,"<",$file) or die $!;
my ($n,$bad)=(0,0);
while(my $l=<$fh>){
  chomp $l; next if $l=~/^\s*$/ || $l=~/^#/;
  my @a=split /\s+/,$l;
  my @q=map{my $s=$_;$s=~s/'/'\\''/g;"'$s'"}@a;
  my $j=join(" ",@q);
  my $oc=`$CPP $j 2>/tmp/e1`; my $ec=`cat /tmp/e1`;
  my $orr=`$RUST $j 2>/tmp/e2`; my $er=`cat /tmp/e2`;
  $n++;
  if($oc ne $orr || $ec ne $er){
    $bad++;
    print "MISMATCH args=[$l]\n";
    my @lc=split/\n/,$oc; my @lr=split/\n/,$orr;
    my $m=@lc>@lr?@lc:@lr;
    for my $i (0..$m-1){
      my $x=$i<@lc?$lc[$i]:"<missing>"; my $y=$i<@lr?$lr[$i]:"<missing>";
      next if $x eq $y;
      print "  cpp : $x\n  rust: $y\n";
      my @ta=split/\s+/,$x; my @tb=split/\s+/,$y;
      my $mx=@ta>@tb?@ta:@tb;
      for my $k (0..$mx-1){
        my $p=$k<@ta?$ta[$k]:"<>"; my $qq=$k<@tb?$tb[$k]:"<>";
        print "    field $k: cpp=$p rust=$qq\n" if $p ne $qq;
      }
    }
    print "  stderr cpp=[$ec] rust=[$er]\n" if $ec ne $er;
    last if $bad>=8;
  }
}
print "probes=$n mismatches=$bad\n";

